DECLARE TEMP VARCHAR2(1);
BEGIN TEMP := NULL;
INSERT INTO IF_PROGRESS( BUYER, GUBUN, LEGACY_NO, REVISION, STATUS, IF_FLAG, TOT_CNT, TOT_AMT, ERR_CNT, ERR_MSG, REMARK, CHANGE_DATE, CHANGE_TIME, CONFIRM_DATE, CONFIRM_TIME, ADD_DATE )VALUES( NVL(TRIM($PROG_BUYER$), ' '), 'PO', NVL(TRIM($PROG_LEGACY_NO$), ' '), NVL(TRIM($PROG_REVISION$), ' '), NVL(TRIM($PROG_STATUS$), ' '), NVL(TRIM($PROG_IF_FLAG$), ' '), NVL($PROG_TOT_CNT$, 0 ), NVL($PROG_TOT_AMT$, 0 ), NVL($PROG_ERR_CNT$, 0 ), NVL(TRIM($PROG_ERR_MSG$), ' '), NVL(TRIM($PROG_REMARK$), ' '), NVL(TRIM($PROG_CHANGE_DATE$), ' '), NVL(TRIM($PROG_CHANGE_TIME$), ' '), NVL(TRIM($PROG_CONFIRM_DATE$), ' '), NVL(TRIM($PROG_CONFIRM_TIME$), ' '), NVL(TRIM($PROG_ADD_DATE$), ' ') );
INSERT INTO IF_PODT( BUYER, LEGACY_PO_NO, LEGACY_PO_SEQ, REVISION, STATUS, BUYER_ITEM_NO, CURRENCY_CODE, UNIT_PRICE, ITEM_QTY, ITEM_AMT, ADD_DATE, RD_DATE, DELY_TO_LOCATION, PURCHASER_USER_ID, PURCHASER_USER_DEPT, AGENT, CONTRACT_NO, CONTRACT_SEQ, LEGACY_SELLER_CODE, LEGACY_PR_NO, REQ_USER_ID, REQ_USER_NAME, REQ_USER_DEPT, REQ_USER_DEPT_NAME, REMARK, REMARK2, ERROR_MSG, REF_IF_NO, DOC_TYPE, FILE_NAME, SELLER, IF_FLAG, LOAD_DATE, LOAD_TIME, BYIT_COMORG_CODE, REQ_USER_INFO )VALUES( NVL(TRIM($POIF_BUYER$),' '), NVL(TRIM($POIF_LEGACY_PO_NO$),' '), NVL(TRIM($POIF_LEGACY_PO_SEQ$),' '), NVL(TRIM($POIF_REVISION$),' '), NVL(TRIM($POIF_STATUS$),' '), NVL(TRIM($POIF_BUYER_ITEM_NO$),' '), NVL(TRIM($POIF_CURRENCY_CODE$),' '), NVL($POIF_UNIT_PRICE$,0), NVL($POIF_ITEM_QTY$,0), NVL($POIF_ITEM_AMT$,0), NVL(TRIM($POIF_ADD_DATE$),' '), NVL(TRIM($POIF_RD_DATE$),' '), NVL(TRIM($POIF_DELY_TO_LOCATION$),' '), NVL(TRIM($POIF_PURCHASER_USER_ID$),' '), NVL(TRIM($POIF_PURCHASER_USER_DEPT$),' '), NVL(TRIM($POIF_AGENT$),' '), NVL(TRIM($POIF_CONTRACT_NO$),' '), NVL(TRIM($POIF_CONTRACT_SEQ$),' '), NVL(TRIM($POIF_LEGACY_SELLER_CODE$),' '), NVL(TRIM($POIF_LEGACY_PR_NO$),' '), NVL(TRIM($POIF_REQ_USER_ID$),' '), NVL(TRIM($POIF_REQ_USER_NAME$),' '), NVL(TRIM($POIF_REQ_USER_DEPT$),' '), NVL(TRIM($POIF_REQ_USER_DEPT_NAME$),' '), NVL(TRIM($POIF_REMARK$),' '), NVL(TRIM($POIF_REMARK2$),' '), NVL(TRIM($POIF_ERROR_MSG$),' '), NVL(TRIM($POIF_REF_IF_NO$),' '), NVL(TRIM($POIF_DOC_TYPE$),' '), NVL(TRIM($POIF_FILE_NAME$),' '), NVL(TRIM($POIF_SELLER$) ,' '), NVL(TRIM($POIF_IF_FLAG$) ,' '), NVL(TRIM($POIF_LOAD_DATE$),' '), NVL(TRIM($POIF_LOAD_TIME$),' '), NVL(TRIM($POIF_BYIT_COMORG_CODE$),' '), NVL(TRIM(SUBSTRB(NVL($POIF_REQ_USER_NAME$,' ')||' '||NVL($POIF_REQ_USER_DEPT_NAME$,' '),1,50)),' ') );
END;
